// Fasting Timer Chrome Extension - Lógica compartida con GNOME Shell extension
// Esta versión está compilada para uso en navegador web

// BACKEND API ENDPOINTS (Mismo backend que usa GNOME extension)
const BASE_URL = window.gfasting_timer || "http://localhost:3001";

// Configuration - Declaración CORRECTA de variables globales (ERROR GNOME FIXED ✅)
const DEFAULT_PORT = 3001;
const HOSTNAME = "localhost";
const TIEMPO_ESPERA_SEGUNDS = 4500; // 4500 segundos (el tiempo de espera del backend)
const TIEMPO_ESPERA_MINUTOS = TIEMPO_ESPERA_SEGUNDS / 60; // Convertido a minutos para UI
const DEFAULT_DURATION_SECONDS = TIEMPO_ESPERA_SEGUNDS * 1000; // En milisegundos como requiere el temporizador

// DATE INICIAL CON DECLARACIÓN PROPIA
const START_DATE = new Date();

// API calls (misma función que GNOME extension)
function logClick(elapsedSeconds) {
  fetch(`${BASE_URL}/api/end`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ interval: elapsedSeconds })
  }).then(r => r.ok ? null : console.warn("Log click failed")).catch(e => console.error(e));
}

async function getStats() {
  return fetch(`${BASE_URL}/api/stats`).then(r => r.json());
}

// Main extension logic (shared with GNOME)
function initFastingTimer(displayElement, statsElements) {
  let timerId = null;
  let timerStart = null;
  let remaining = TIEMPO_ESPERA_SEGUNDS;
  
  // Reset button handler
  document.getElementById('resetBtn').addEventListener('click', resetTimer);
  
  function logToConsole() {
    console.log(`# Fasting Timer - Tiempo restante: ${Math.ceil(remaining/60)}m`);
    console.log(`📊 Stats: Total sessions:`, getStatsAsync());
  }
  
  async function getStatsAsync() {
    try {
      const stats = await getStats();
      document.getElementById('totalSessions').textContent = stats.total_sessions || 0;
      document.getElementById('weeklyAvg').textContent = stats.weekly_average_minutes ? 
        Math.round(stats.weekly_average_minutes * 60) + 's' : '---';
      document.getElementById('monthlyAvg').textContent = stats.monthly_average_minutes ? 
        Math.round(stats.monthly_average_minutes * 60) + 's' : '---';
    } catch (e) {
      console.error("Stats error:", e);
    }
  }
  
  function resetTimer() {
    // Stop existing timer
    if (timerId) {
      clearTimeout(timerId);
      timerId = null;
    }
    
    // Log current elapsed time
    if (Date.now()) {
      const elapsed = Date.now() - (timerStart || 0);
      logClick(elapsed / 1000);
    }
    
    // Reset UI
    displayElement.textContent = `# ${Math.ceil(TIEMPO_ESPERA_MINUTOS)}m`;
    remaining = TIEMPO_ESPERA_SEGUNDS;
    timerStart = Date.now();
    
    logToConsole();
    getStatsAsync();
  }
  
  function startTimer() {
    // Display initial state
    displayElement.textContent = `# ${Math.ceil(TIEMPO_ESPERA_MINUTOS)}m`;
    remaining = TIEMPO_ESPERA_SEGUNDS;
    
    // Start timer interval
    timerId = setInterval(() => {
      remaining--;
      
      if (remaining > 0) {
        displayElement.textContent = `# ${Math.ceil(remaining / 60)}m`;
      } else {
        // Timer finished
        displayElement.textContent = "# ✅";
        logClick(TIEMPO_ESPERA_SEGUNDS);
        clearInterval(timerId);
        timerId = null;
        
        // Update stats
        getStatsAsync();
      }
    }, 1000); // Update every second
    
    timerStart = Date.now();
    
    // Log initial state
    logToConsole();
  }
  
  // Auto-start on load (GNOME doesn't auto-count, Chrome can)
  setTimeout(() => {
    if (!confirm("⏱️ ¿Iniciar temporizador automáticamente?")) return;
    startTimer();
    getStatsAsync(); // Muestra estadísticas móviles INMEDIATAMENTE al iniciar timer
  }, 1000);
}

// Initialize when DOM is ready
document.addEventListener('DOMContentLoaded', () => {
  initFastingTimer(
    document.getElementById('timerDisplay'),
    [
      document.getElementById('totalSessions'),
      document.getElementById('weeklyAvg'),
      document.getElementById('monthlyAvg')
    ]
  );
});

// Export function for external use if needed
window.SmokeTimerAPI = {
  start: () => console.log("Fasting Timer started (manual trigger)"),
  stop: () => console.log("Fasting Timer stopped")
};
